mapper.sql:
SELECT ic.work_order_id, icd.item_id AS raw_item_id, icd.batch_id AS raw_batch_id, icd.batch_code AS raw_batch_code, ppd.item_id AS product_item_id, ppd.batch_id AS product_batch_id, ppd.batch_code AS product_batch_code FROM mes_wm_item_consume_detail icd INNER JOIN mes_wm_item_consume ic ON ic.id = icd.consume_id AND ic.tenant_id = #{tenantId} AND ic.deleted = 0 AND ic.status = 4 INNER JOIN mes_pro_feedback pf ON pf.id = ic.feedback_id AND pf.work_order_id = ic.work_order_id AND pf.tenant_id = #{tenantId} AND pf.deleted = 0 AND pf.status = 4 INNER JOIN mes_wm_product_produce pp ON pp.feedback_id = pf.id AND pp.work_order_id = ic.work_order_id AND pp.tenant_id = #{tenantId} AND pp.deleted = 0 AND pp.status = 4 INNER JOIN mes_wm_product_produce_detail ppd ON ppd.produce_id = pp.id AND ppd.item_id = pf.item_id AND ppd.tenant_id = #{tenantId} AND ppd.deleted = 0 AND ppd.quantity > 0 WHERE icd.tenant_id = #{tenantId} AND icd.deleted = 0 AND icd.quantity > 0 AND icd.batch_code IS NOT NULL AND icd.batch_code != '' AND ppd.batch_code IS NOT NULL AND ppd.batch_code != ''
AND icd.batch_code = #{batchCode} AND ppd.batch_code = #{batchCode}
UNION
SELECT st.work_order_id, sm.item_id AS raw_item_id, sm.batch_id AS raw_batch_id, sm.batch_code AS raw_batch_code, ppd.item_id AS product_item_id, ppd.batch_id AS product_batch_id, ppd.batch_code AS product_batch_code FROM mes_pro_sn_trace st INNER JOIN mes_pro_sn_station ss ON ss.trace_id = st.id AND ss.work_order_id = st.work_order_id AND ss.tenant_id = #{tenantId} AND ss.deleted = 0 INNER JOIN mes_pro_sn_material sm ON sm.trace_id = st.id AND sm.station_id = ss.id AND sm.feedback_id = ss.feedback_id AND sm.tenant_id = #{tenantId} AND sm.deleted = 0 AND sm.quantity > 0 INNER JOIN mes_wm_item_consume ic ON ic.id = sm.consume_id AND ic.feedback_id = ss.feedback_id AND ic.work_order_id = st.work_order_id AND ic.tenant_id = #{tenantId} AND ic.deleted = 0 AND ic.status = 4 INNER JOIN mes_wm_item_consume_detail icd ON icd.id = sm.consume_detail_id AND icd.consume_id = ic.id AND icd.line_id = sm.consume_line_id AND icd.item_id = sm.item_id AND icd.batch_code = sm.batch_code AND (icd.batch_id = sm.batch_id OR (icd.batch_id IS NULL AND sm.batch_id IS NULL)) AND icd.tenant_id = #{tenantId} AND icd.deleted = 0 AND icd.quantity >= sm.quantity INNER JOIN mes_pro_feedback pf ON pf.id = ss.feedback_id AND pf.work_order_id = st.work_order_id AND pf.item_id = st.product_id AND pf.tenant_id = #{tenantId} AND pf.deleted = 0 AND pf.status = 4 INNER JOIN mes_pro_sn_station os ON os.trace_id = st.id AND os.work_order_id = st.work_order_id AND os.tenant_id = #{tenantId} AND os.deleted = 0 INNER JOIN mes_pro_feedback opf ON opf.id = os.feedback_id AND opf.work_order_id = st.work_order_id AND opf.item_id = st.product_id AND opf.tenant_id = #{tenantId} AND opf.deleted = 0 AND opf.status = 4 INNER JOIN mes_wm_product_produce pp ON pp.feedback_id = os.feedback_id AND pp.work_order_id = st.work_order_id AND pp.tenant_id = #{tenantId} AND pp.deleted = 0 AND pp.status = 4 INNER JOIN mes_wm_product_produce_detail ppd ON ppd.produce_id = pp.id AND ppd.item_id = st.product_id AND ppd.tenant_id = #{tenantId} AND ppd.deleted = 0 AND ppd.quantity > 0 WHERE st.tenant_id = #{tenantId} AND st.deleted = 0 AND st.status = 'COMPLETED' AND sm.batch_code IS NOT NULL AND sm.batch_code != '' AND ppd.batch_code IS NOT NULL AND ppd.batch_code != ''
AND sm.batch_code = #{batchCode} AND ppd.batch_code = #{batchCode}
UNION
SELECT source.work_order_id, icd.item_id AS raw_item_id, icd.batch_id AS raw_batch_id, icd.batch_code AS raw_batch_code, ppd.item_id AS product_item_id, ppd.batch_id AS product_batch_id, ppd.batch_code AS product_batch_code FROM mes_pro_feedback_ancestor a INNER JOIN mes_pro_feedback target ON target.id=a.feedback_id AND target.tenant_id=#{tenantId} AND target.deleted=0 AND target.status=4 INNER JOIN mes_pro_feedback source ON source.id=a.ancestor_feedback_id AND source.work_order_id=target.work_order_id AND source.item_id=target.item_id AND source.route_id=target.route_id AND source.tenant_id=#{tenantId} AND source.deleted=0 AND source.status=4 INNER JOIN mes_wm_item_consume ic ON ic.feedback_id=source.id AND ic.work_order_id=source.work_order_id AND ic.tenant_id=#{tenantId} AND ic.deleted=0 AND ic.status=4 INNER JOIN mes_wm_item_consume_detail icd ON icd.consume_id=ic.id AND icd.tenant_id=#{tenantId} AND icd.deleted=0 AND icd.quantity>0 INNER JOIN mes_wm_product_produce pp ON pp.feedback_id=target.id AND pp.work_order_id=target.work_order_id AND pp.tenant_id=#{tenantId} AND pp.deleted=0 AND pp.status=4 INNER JOIN mes_wm_product_produce_detail ppd ON ppd.produce_id=pp.id AND ppd.item_id=target.item_id AND ppd.tenant_id=#{tenantId} AND ppd.deleted=0 AND ppd.quantity>0 WHERE a.tenant_id=#{tenantId} AND a.deleted=0 AND EXISTS(SELECT 1 FROM mes_pro_feedback_source frozen_source WHERE frozen_source.feedback_id=target.id AND frozen_source.tenant_id=#{tenantId} AND frozen_source.frozen=1 AND frozen_source.deleted=0 AND frozen_source.quantity>0) AND icd.batch_code IS NOT NULL AND icd.batch_code!='' AND ppd.batch_code IS NOT NULL AND ppd.batch_code!=''
AND icd.batch_code=#{batchCode} AND ppd.batch_code=#{batchCode}
